function applyTranslations(lang) {
    document.querySelectorAll('[data-t]').forEach(el => {
        const key = el.getAttribute('data-t');
        if (translations[lang] && translations[lang][key]) {
            el.textContent = translations[lang][key];
        } else if (timelineData[lang] && timelineData[lang][key]) {
            const data = timelineData[lang][key];
            if (typeof data === 'string') {
                el.textContent = data;
            } else if (data.title) {
                // If the element is a container for title/desc (like h4 or p)
                if (el.tagName === 'H4') el.textContent = data.title;
                else if (el.tagName === 'P') el.textContent = data.desc;
            }
        }
    });
    document.querySelectorAll('[data-t-html]').forEach(el => {
        const key = el.getAttribute('data-t-html');
        if (translations[lang] && translations[lang][key]) {
            el.innerHTML = translations[lang][key];
        }
    });
    document.documentElement.lang = lang;
}

function openProjectModal(id) {
    const lang = localStorage.getItem('language') || 'en';
    const data = projectData[lang][id];
    if (!data) return;
    
    // Call the original openModal function (defined in index.html) with the ID and localized data
    if (typeof openModal === 'function') {
        openModal(id, data.title, data.type, data.desc, data.techs, data.link, data.image, data.year || '', data.extra || {});
    }
}

